/** Replies generated by xterm are protocol traffic, not human Shell editing. */
export function stripTerminalReplies(data: string): string {
  return data
    .replace(/\x1b\[(?:[?>=]?\d+(?:;\d+)*)[Rcn]|\x1b\[\?\d+u|\x1b\[[IO]/g, '')
    .replace(/\x1b\[\??\d+;\d+\$y/g, '')
    .replace(/\x1bP[01]\$r[^\x1b]*\x1b\\/g, '')
    .replace(/\x1b\](?:4;\d+|10|11|12);[^\x07\x1b]*(?:\x07|\x1b\\)/g, '')
}
